def decode_string(s: str) -> str:
    stack = [["", 0]]  # each entry: [current decoded string, repeat count]

    for ch in s:
        if ch.isdigit():
            stack[-1][1] = stack[-1][1] * 10 + int(ch)
        elif ch == '[':
            stack.append(["", 0])
        elif ch == ']':
            text, k = stack.pop()
            stack[-1][0] += text * k
        else:
            stack[-1][0] += ch

    return stack[0][0]
```

